package dev.industrialtechnology.railway;
import java.util.*;import net.minecraftforge.common.ForgeChunkManager;import net.minecraftforge.common.ForgeChunkManager.Ticket;import net.minecraft.world.ChunkCoordIntPair;import dev.industrialtechnology.core.IndustrialTechnology;import dev.industrialtechnology.expansion.ExpansionConfig;
public final class RailwayTickets {
 private Ticket ticket;private final EntityRollingStock engine;public RailwayTickets(EntityRollingStock e){engine=e;}public boolean update(List<EntityRollingStock> consist){if(!ExpansionConfig.trainChunks||engine.worldObj.isRemote)return true;if(engine.throttle<=0&&engine.speed<.001){release();return true;}if(ticket==null){ticket=ForgeChunkManager.requestTicket(IndustrialTechnology.instance,engine.worldObj,ForgeChunkManager.Type.ENTITY);if(ticket==null)return false;ticket.bindEntity(engine);ticket.getModData().setBoolean("Railway",true);}
 Set<ChunkCoordIntPair> wanted=new LinkedHashSet<>();for(EntityRollingStock e:consist){int x=((int)Math.floor(e.posX))>>4,z=((int)Math.floor(e.posZ))>>4;wanted.add(new ChunkCoordIntPair(x,z));if(e.rail!=null){TileTrack anchor=TrackWorld.get(engine.worldObj,e.rail.track);if(anchor!=null)wanted.add(new ChunkCoordIntPair(anchor.xCoord>>4,anchor.zCoord>>4));for(double offset:new double[]{-e.stock.length/2,e.stock.length/2}){TrackWorld.Cursor c=e.rail.copy();if(c.move(engine.worldObj,offset)){double[] point=c.point(engine.worldObj);wanted.add(new ChunkCoordIntPair(((int)Math.floor(point[0]))>>4,((int)Math.floor(point[2]))>>4));TileTrack t=TrackWorld.get(engine.worldObj,c.track);if(t!=null)wanted.add(new ChunkCoordIntPair(t.xCoord>>4,t.zCoord>>4));}}}}int ex=((int)Math.floor(engine.posX))>>4,ez=((int)Math.floor(engine.posZ))>>4;int depth=Math.min(ExpansionConfig.chunkLimit,Math.min(ticket.getMaxChunkListDepth(),ticket.getChunkListDepth()));if(wanted.size()>depth||depth<1)return false;final double headingX=-Math.sin(Math.toRadians(engine.rotationYaw)),headingZ=Math.cos(Math.toRadians(engine.rotationYaw));List<ChunkCoordIntPair> nearby=new ArrayList<>();for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)nearby.add(new ChunkCoordIntPair(ex+x,ez+z));nearby.sort((a,b)->Double.compare((b.chunkXPos-ex)*headingX+(b.chunkZPos-ez)*headingZ,(a.chunkXPos-ex)*headingX+(a.chunkZPos-ez)*headingZ));for(ChunkCoordIntPair p:nearby)if(wanted.size()<depth)wanted.add(p);for(ChunkCoordIntPair p:new ArrayList<>(ticket.getChunkList()))if(!wanted.contains(p))ForgeChunkManager.unforceChunk(ticket,p);for(ChunkCoordIntPair p:wanted)if(!ticket.getChunkList().contains(p))ForgeChunkManager.forceChunk(ticket,p);return ticket.getChunkList().containsAll(wanted);}
 public void adopt(Ticket t){if(ticket==null)ticket=t;else ForgeChunkManager.releaseTicket(t);}public void release(){if(ticket!=null){ForgeChunkManager.releaseTicket(ticket);ticket=null;}}
}
